<div class="flex flex-col gap-3 rounded-xl border border-orange-200 bg-orange-50 p-3.5 md:flex-row md:items-center md:justify-between md:px-6 md:py-4 dark:border-orange-900 dark:bg-orange-950/40">
<p class="text-sm text-orange-900 md:text-base dark:text-orange-200"><?= e(__('available_translations')) ?></p><nav class="flex flex-wrap gap-2" aria-label="<?= e(__('translation')) ?>"><?php foreach ($otherTranslations as $translation): ?><a class="inline-flex min-h-11 flex-1 items-center justify-center whitespace-nowrap rounded-lg border border-orange-300 bg-white px-4 font-semibold text-orange-900 dark:border-orange-800 dark:bg-transparent dark:text-orange-300" lang="<?= e($translation['code']) ?>" href="<?= e('/' . $translation['code'] . $suffix) ?>"><?= e($translation['native_name']) ?></a><?php endforeach ?></nav></div><?php endif ?>
<header class="flex max-w-[820px] flex-col gap-4 md:gap-5">
