<?php if (!$isPage): ?><p class="order-first font-mono text-xs text-slate-600 md:order-none md:hidden dark:text-slate-400"><?= e(localized_date($item['published_at'])) ?> · <?= e(__('reading_minutes', ['minutes' => $item['reading_minutes']])) ?></p><?php endif ?>
<h1 class="p-name text-[32px] leading-tight font-bold tracking-tight md:text-[64px] md:leading-[1.04] md:tracking-[-.035em]"><?= e($item['title']) ?></h1><?php if (!$isPage): ?><data class="u-url" value="<?= e(absolute_url('/' . $locale . $suffix)) ?>"></data><?php endif ?>
<p class="p-summary hidden font-serif text-[22px] leading-normal text-slate-700 md:block dark:text-slate-300"><?= e($item['summary']) ?></p>
<?php if (!$isPage): ?><div class="hidden flex-wrap items-center gap-x-5 gap-y-2 font-mono text-xs text-slate-600 md:flex dark:text-slate-400"><span><?= e(__('published')) ?> <time class="dt-published" datetime="<?= e($item['published_at']) ?>"><?= e(localized_date($item['published_at'])) ?></time></span><span><?= e(__('reading_minutes', ['minutes' => $item['reading_minutes']])) ?></span><div class="flex flex-wrap gap-1.5"><?php foreach ($tags as $tag): ?><a class="p-category tag" href="<?= e('/' . $locale . '/tags/' . rawurlencode($tag['slug'])) ?>">#<?= e($tag['name']) ?></a><?php endforeach ?></div></div><?php endif ?>
</header>
<?php if (!$isPage && !empty($item['cover_image'])): ?><figure class="h-[220px] overflow-hidden rounded-2xl md:h-[380px]"><?php $post = $item; require __DIR__ . '/../partials/cover.php' ?></figure><?php endif ?>
<?php if (!$isPage && $item['toc_html'] !== ''): ?><details class="rounded-xl border border-slate-200 bg-white md:hidden dark:border-slate-800 dark:bg-slate-900"><summary class="flex min-h-12 cursor-pointer items-center justify-between px-4 font-semibold"><?= e(__('on_this_page')) ?><span aria-hidden="true">⌄</span></summary><div class="toc-meteor p-3"><?= $item['toc_html'] ?></div></details><?php endif ?>
<div class="flex items-start gap-14"><article class="e-content prose-meteor min-w-0 flex-1 md:flex-[0_1_700px]"><?= $item['content_html'] ?></article>
<?php if (!$isPage && $item['toc_html'] !== ''): ?><aside aria-labelledby="toc-title" class="sticky top-6 hidden min-w-60 flex-[1_1_240px] rounded-[14px] border border-slate-200 bg-white p-6 md:block dark:border-slate-800 dark:bg-slate-900"><h2 id="toc-title" class="eyebrow mb-3"><?= e(__('on_this_page')) ?></h2><div class="toc-meteor"><?= $item['toc_html'] ?></div><?php if (!empty($item['category_name'])): ?><div class="mt-4 border-t border-slate-200 pt-3 dark:border-slate-800"><p class="text-sm text-slate-600 dark:text-slate-400"><?= e(__('category')) ?></p><a class="accent inline-flex min-h-11 items-center font-semibold" href="<?= e('/' . $locale . '/categories/' . rawurlencode($item['category_slug'])) ?>"><?= e($item['category_name']) ?></a></div><?php endif ?></aside><?php endif ?></div>
<?php if (!$isPage): $authorCard = $author !== null && $settings->global('post_author_card') === '1'; ?>
<?php if ($tags || $authorCard): // Tags (on small screens) and the author card, below a line like the one above Previous/Next. ?>
<div class="<?= $authorCard ? 'flex' : 'flex md:hidden' ?> flex-col gap-6 border-t border-slate-200 pt-6 dark:border-slate-800">
<?php if ($tags): ?><div class="flex flex-wrap gap-2 md:hidden"><?php foreach ($tags as $tag): ?><a class="tag" href="<?= e('/' . $locale . '/tags/' . rawurlencode($tag['slug'])) ?>">#<?= e($tag['name']) ?></a><?php endforeach ?></div><?php endif ?>
<?php if ($authorCard): ?><section aria-labelledby="author-heading" class="max-w-[700px]"><h2 id="author-heading" class="eyebrow mb-4"><?= e(__('about_author')) ?></h2><div class="rounded-2xl border border-slate-200 bg-white p-5 md:p-7 dark:border-slate-800 dark:bg-slate-900"><?php $card = $author; $cardVariant = 'post'; require __DIR__ . '/../partials/author-card.php' ?></div></section><?php endif ?>
</div>
<?php endif ?>
<?php if (array_filter($neighbors)): ?><nav aria-label="<?= e(__('more_posts')) ?>" class="grid gap-4 border-t border-slate-200 pt-6 md:grid-cols-2 dark:border-slate-800"><?php foreach ($neighbors as $rel => $neighbor): if (!$neighbor) { continue; } ?><a class="flex flex-col gap-2 rounded-[14px] border border-slate-200 bg-white p-6 dark:border-slate-800 dark:bg-slate-900" rel="<?= e($rel) ?>" href="<?= e('/' . $locale . '/posts/' . rawurlencode($neighbor['slug'])) ?>"><span class="eyebrow"><?= e(__($rel === 'prev' ? 'previous' : 'next')) ?></span><span class="text-xl font-semibold"><?= e($neighbor['title']) ?></span></a><?php endforeach ?></nav><?php endif ?>
<?php endif ?>
</div>
